      SUBROUTINE RDVCINC---- CONVERT EXTERNAL VARY CODES TO INTERNALC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2B.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'KELEM.CIN'C-----------------------------------------------------------------------      DATA            NVMAXP /10/C-----------------------------------------------------------------------C      NORD1 = 1      NV1 = 0      NVMAX = NPVAR      DO 510 J = 1, NPVAR  510 VSTOR(J) = 0C      DO 520 NUM = 1, NEL      I = ISTOR(NUM)      NTYPE = IDATA(I)      IF (NTYPE .EQ. 17) NORD1 = INT(DATA(I+1))  520 CONTINUEC      IF (NORD1 .GE. 2) NVMAX = NVMAXPC      IOLD = 0      DO 700 NUM = 1, NEL      I = ISTOR(NUM)      ITYPE = I      IF (I .LE. IOLD) GO TO 700      NTYPE = IDATA(I)      IF (NTYPE .LE. 0 .OR. NTYPE .GE. 50) GO TO 700      IF (NTYPE .EQ. 10) GO TO 700      IBEG = I + 1      NUM1 = NUM  601 IEND = ISTOR(NUM1 + 1)      IF (IEND .LT. IBEG) THEN        NUM1 = NUM1 + 1        GO TO 601      ENDIF  605 IEND = IEND - 1      DO 690 I = IBEG, IEND      IVARY = IABS(TIE(I))      IF (IVARY .GE. 99) GO TO 690      IF (IVARY .EQ. 0) GO TO 690      IF (IVARY .EQ. 1) GO TO 650      IF (IVARY .GE. 7 .AND. IVARY .LE. 9) THEN        IVARY = IVARY - 5        TIE(I) = - TIE(I)      ENDIF      IF (NV1 .GT. 0) THEN        DO 630 NN = 1, NV1        N = NN        IF (VSTOR(N) .EQ. IVARY) GO TO 680  630   CONTINUE      ENDIF  650 IF (NV1 .GE. NVMAX) THEN        WRITE (NOUT, 9660) KELEM(NTYPE), LABEL(NUM), NVMAX        TIE(I) = 0        GO TO 690      ELSE        NV1 = NV1 + 1        VSTOR(NV1) = IVARY        N = NV1      ENDIF  680 TIE(I) = ISIGN(N, TIE(I))  690 CONTINUE  700 IOLD = MAX0(ITYPE,IOLD)C      RETURNC 9660 FORMAT ('0*** ERROR *** PARAMETER NOT VARIED FOR ',A8,1X,A8,     1       ' -- TOO MANY VARIED PARAMETERS, ONLY ',I2,' ALLOWED')      END